    ROLE_ID_TO_ADD: "995154994183548953",
    LOG_CHANNEL_ID: "1264758034979360860",
    MANAGE_CHANNEL_ID: "1264980225150681098",
    APPS_IDS: {
        bateponto1: "0c2a35af2e864f188d7b5cfb63681e89",
